head.script:
// 테스트 설명, 유효성 값 설정
scwin.tData = {
    "description" : "[treeview > M > removeNodeClass]<br/>트리 아이템 객체를 사용하여 특정 트리 아이템을 제거합니다.",
    "validation" : [
        "트리 아이템의 인덱스는 Depth-First Search 방식으로 설정되며, moveNode() 메소드 실행 시 인덱스가 재설정 됩니다.",
    ]
}



scwin.onpageload = function () {
    wf_body_left.getObj("scwin").createValidation(scwin.tData);	

    // Global DataList 생성 호출
    $c.gcm.createCommonDatalist();

    // comp 초기 생성
    scwin.comp_init();
};



// comp 생성
scwin.comp_init = async function () {
    // 기존 target 있으면 삭제
    if (typeof target1 !== 'undefined') {
        target1.remove();
    }

    let properties = {
        renderType : "table",
    }

    let cList = $c.gcm.createCList(properties);    

    $c.gcm.createLabel('label="moveNode 를 수행하여 마지막 아이템을 index=2 위치로 이동 후 removeNodeClass 수행하여 확인"', '', 'label1'); 

    $c.gcm.createBasicTreeView(cList);     
}



scwin.btn_getClassName_onclick = function (e) {
    let index = par_index.getText();

    if (index !== "") {
        if (target1.options.renderType == "virtual") {

            let divElements = document.querySelectorAll('div[id*="target1_node"]');

            debugger;

            if (divElements.length > 0) {
                if(index == 1) {                    
                    for (var i=index-1; i < 2; i++) {
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] tagName: " + divElements[i].tagName);   
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] className: " + divElements[i].className);   
                    }
                }
                else if(index == 3) {
                    for (var i=index-1; i < 6; i++) {
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] tagName: " + divElements[i].tagName);   
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] className: " + divElements[i].className);   
                    }
                }
                else if(index == 6) {
                    for (var i=index-1; i < 11; i++) {
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] tagName: " + divElements[i].tagName);   
                        wf_body_bottom.getObj("scwin").setReturnValue("item["+i+"] className: " + divElements[i].className);   
                    }
                }
                else {
                    wf_body_bottom.getObj("scwin").setReturnValue("item["+index+"] tagName: " + divElements[index-1].tagName);   
                    wf_body_bottom.getObj("scwin").setReturnValue("item["+index+"] className: " + divElements[index-1].className);                       
                }
            }
        }
        else {
            let tableElement = document.querySelector('table[id*="target1_node_'+index+'"]');

            if (tableElement) {
                wf_body_bottom.getObj("scwin").setReturnValue("item["+index+"] tagName: " + tableElement.tagName);               
                wf_body_bottom.getObj("scwin").setReturnValue("item["+index+"] className : " + tableElement.className);               
            }

            let childTables = tableElement.querySelectorAll('table');

            childTables.forEach((childTable, childIndex) => {
                let currentChildIndex = Number(index) + 1 + Number(childIndex); // Increment the index for the child tables
                wf_body_bottom.getObj("scwin").setReturnValue("item[" + currentChildIndex + "] tagName: " + childTable.tagName);
                wf_body_bottom.getObj("scwin").setReturnValue("item[" + currentChildIndex + "] className: " + childTable.className);

                let subChildTables = childTable.querySelectorAll('table');   

                subChildTables.forEach((subChildTable, subChildIndex) => {
                    let currentSubChildIndex = Number(currentChildIndex) + 1 + Number(subChildIndex); // Increment the index for the child tables
                    wf_body_bottom.getObj("scwin").setReturnValue("item[" + currentSubChildIndex + "] tagName: " + subChildTable.tagName);
                    wf_body_bottom.getObj("scwin").setReturnValue("item[" + currentSubChildIndex + "] className: " + subChildTable.className);
                });
            });
        }
    }
};



scwin.brn_removeNodeClass_onclick = function (e) {
    let index = Number(par_index.getText());    
    let applyChildNodes = par_applyChildNodes.getText();
    let cssName = par_cssName.getText();

    if (applyChildNodes == "true")
        applyChildNodes = true;

    if (applyChildNodes == "false")
        applyChildNodes = false;

    if (applyChildNodes == "" && cssName == "")
        target1.removeNodeClass(index);
    else if (applyChildNodes !== "" && cssName == "")
	    target1.removeNodeClass(index, applyChildNodes);
    else
        target1.removeNodeClass(index, applyChildNodes, cssName);

    scwin.btn_getClassName_onclick();
};



scwin.btn_moveNode_onclick = function (e) {
	target1.moveNode(11, 1, true);

    target1.setNodeClass(1, "nodeClass nodeClass2", true);
    target1.setNodeClass(4, "nodeClass nodeClass2", true);
    target1.setNodeClass(7, "nodeClass nodeClass2", true);    
};
